Map<String, dynamic> sampleBookedSlotJson({
  String timeRange = '06:00 PM - 07:00 PM',
  String fromTime = '18:00:00',
  String toTime = '19:00:00',
}) {
  return {
    'time_range': timeRange,
    'from_time': fromTime,
    'to_time': toTime,
  };
}

Map<String, dynamic> sampleBookingPaymentJson({
  String paymentMethod = 'razorpay',
  num amount = 1000.0,
  String paidAt = '2026-10-17 12:00:00',
}) {
  return {
    'payment_method': paymentMethod,
    'amount': amount,
    'paid_at': paidAt,
  };
}

Map<String, dynamic> sampleCancellationBreakupJson({
  num grossPaid = 1200.0,
  num turfCancellationFee = 120.0,
  num platformFeeRetained = 20.0,
  num saasCancellationFee = 0.0,
  num totalDeductions = 140.0,
  num refundAmount = 1060.0,
}) {
  return {
    'gross_paid': grossPaid,
    'turf_cancellation_fee': turfCancellationFee,
    'platform_fee_retained': platformFeeRetained,
    'saas_cancellation_fee': saasCancellationFee,
    'total_deductions': totalDeductions,
    'refund_amount': refundAmount,
  };
}

